<script module lang="ts">
/**
 * A scrolling conversation log that follows the newest turn (`design/components/chat-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  SlotOutlet,
  SlotScope,
  agentMember,
  followEnd,
  joinSlot,
  jumpToEnd,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/chat-thread.module.css'
import Button from '../controls/Button.svelte'

export interface ChatThreadMessages {
  jumpToLatest: string
}

export interface ChatThreadProps {
  /**
   * The turns, as ChatMessages in order.
   */
  children?: Snippet
  /**
   * Shown in place of the turns while there are none, such as an EmptyState or a Hero.
   */
  empty?: Snippet
  /**
   * The log's accessible name, such as "Conversation" in the app's language.
   */
  label: string
  /**
   * The thread's only built-in text (generic English default), which localized hosts replace.
   */
  messages?: ChatThreadMessages
  /**
   * Whether a reply is arriving, which sets `aria-busy` on the log.
   */
  streaming?: boolean
}
</script>

<script lang="ts">
let {
  children,
  empty,
  label: labelOwn,
  messages = (() => ({ jumpToLatest: 'Jump to latest' }))(),
  streaming = false,
}: ChatThreadProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let detached = $state(false)
let overflowing = $state(false)
let jump = $state<HTMLElement | null>(null)
let list = $state<HTMLElement | null>(null)
let viewport = $state<HTMLElement | null>(null)
const childrenScope: SlotScope = new SlotScope({})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = followEnd(viewport, list, (state) => {
    detached = state.detached
    overflowing = state.overflowing
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1, { watch: () => list })
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'ChatThread',
    element: () => viewport,
    state: () => ({ streaming: streaming }),
    actions: {},
    withholds: () => jump,
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
childrenScope.probe(() => children)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.root}
    data-state={(detached) ? 'detached' : undefined}
    data-streaming={(streaming) ? '' : undefined}
    data-member="chat-thread"
    ><div
      bind:this={viewport}
      class={styles.viewport}
      data-chat-thread-part="viewport"
      role="log"
      aria-label={label}
      aria-relevant="additions"
      aria-busy={(streaming) ? true : undefined}
      tabindex={((overflowing) ? '0' : undefined) as never}
      >{#if childrenScope.read().count === 0
        }<div class={styles.empty}>{@render empty?.()}</div
      >{:else
        }<div bind:this={list} class={styles.list}
          ><SlotOutlet scope={childrenScope} snippet={children}
        /></div
      >{/if
    }</div
    ><div bind:this={jump} class={styles.jump}
      ><Button
        variant="outline"
        tone="neutral"
        size="sm"
        icon="down"
        label={messages.jumpToLatest}
        onClick={() => { jumpToEnd(viewport) }}
    /></div
  ></div
>{/if
}{@render joined.end?.()}
